"""Build the dependency-free FT PVT. LIMITED website. Python 3.12+."""
from pathlib import Path
from html import escape
import argparse
import json
import re
import shutil
from urllib.parse import urlparse

ROOT = Path(__file__).resolve().parent
parser = argparse.ArgumentParser()
parser.add_argument('--site-url', help='Verified HTTPS origin, e.g. your own domain')
parser.add_argument('--production', action='store_true', help='Require a verified production origin')
args = parser.parse_args()
config = json.loads((ROOT / 'site.config.json').read_text(encoding='utf-8'))
origin = (args.site_url or config['site_url']).rstrip('/')
if origin and (urlparse(origin).scheme != 'https' or not urlparse(origin).netloc or urlparse(origin).path not in ('', '/') or urlparse(origin).query or urlparse(origin).fragment):
    raise SystemExit('site_url must be an HTTPS origin without a path, query or fragment.')
if args.production and not origin:
    raise SystemExit('Production build requires the owner-confirmed domain in site.config.json or --site-url.')
download = config['download_url']
if download and (urlparse(download).scheme != 'https' or not urlparse(download).netloc):
    raise SystemExit('download_url must be a verified HTTPS download or store URL.')
OUT = ROOT / 'dist'
OUT.mkdir(exist_ok=True)
shutil.copytree(ROOT / 'assets', OUT / 'assets', dirs_exist_ok=True)
(OUT / '.nojekyll').write_text('', encoding='utf-8')
COMPANY = 'FT PVT. LIMITED'
EMAIL = 'kcorporation70@gmail.com'
APP = '/apps/all-document-reader/'
POLICY = APP + 'privacy/'
CONTACT = '/contact/'
esc = lambda value: escape(str(value), quote=True)

def button(label, url, secondary=False):
    return f'<a class="btn{" secondary" if secondary else ""}" href="{esc(url)}">{label}</a>'

def get_app():
    return button('Get All Document Reader <span aria-hidden="true">↗</span>' if download else 'Ask about availability <span aria-hidden="true">↗</span>', download or f'mailto:{EMAIL}?subject=All%20Document%20Reader%20Availability')

def bread(items):
    return '<nav class="breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a>' + ''.join(f'<span aria-hidden="true">/</span><a href="{url}">{label}</a>' if url else f'<span aria-hidden="true">/</span><span aria-current="page">{label}</span>' for label,url in items) + '</nav>'

def hero(label, title, desc, crumbs=None):
    return f'<section class="page-hero"><div class="wrap">{bread(crumbs) if crumbs else ""}<span class="eyebrow">{label}</span><h1>{title}</h1><p class="lead">{desc}</p></div></section>'

def panel():
    return f'''<article class="product-panel" aria-label="All Document Reader overview"><div class="panel-top"><span>Our application</span><span>Android</span></div><h2 class="panel-heading">All Document<small>Reader.</small></h2><p class="panel-desc">From the first page to the final detail. Your everyday documents, within reach.</p><div class="product-capabilities"><div class="capability"><strong>Read</strong><span>PDF &amp; office files</span></div><div class="capability"><strong>Find</strong><span>Documents on your device</span></div><div class="capability"><strong>Organize</strong><span>A simpler reading routine</span></div></div><div class="panel-bottom"><span class="tag">Made for everyday reading</span><a href="{APP}">Meet the app <span aria-hidden="true">↗</span></a></div></article>'''

def cards(items):
    return '<div class="grid3">' + ''.join(f'<article class="card"><span class="number">0{i}</span><h3>{title}</h3><p>{body}</p></article>' for i,(title,body) in enumerate(items,1)) + '</div>'

FEATURES = [('Open the document you need','Read PDFs, Word documents, spreadsheets, presentations and text files in one app. Spend less time switching between tools.'),('Find files on your device','Locate supported documents through the file access you choose to grant. Bring everyday reading into one familiar place.'),('Keep reading straightforward','Open, read and organize documents with a focused mobile workflow—whether you are reviewing work or catching up on personal files.')]

def cta():
    return f'<section class="section"><div class="wrap"><div class="cta"><div><h2>A little help goes a long way.</h2><p>Questions about a file, app permissions or your subscription? Get in touch with our team.</p></div>{button("Contact us <span aria-hidden=\"true\">↗</span>",CONTACT)}</div></div></section>'

def faq():
    items = [
      ('Which file formats can I read?', 'All Document Reader supports PDF, DOC, DOCX, XLS, XLSX, PPT, PPTX and TXT. File complexity, encryption or damage can affect how an individual file opens or displays.'),
      ('Is All Document Reader available for iPhone?', 'All Document Reader is an Android app. We have not announced an iPhone version. This website works on Android, iPhone, tablet and desktop browsers.'),
      ('Are my documents uploaded to your servers?', f'Core document reading takes place on your device. FT PVT. LIMITED does not operate a document-upload server for the app. Third-party services handle certain technical, analytics and advertising information. Read the <a href="{POLICY}">app privacy policy</a> for the full details.'),
      ('Do I need an account?', 'An FT PVT. LIMITED account is not required for the main document-reading features. File access depends on the permissions you grant on your device.'),
      ('Does the app contain advertisements?', 'The free version displays advertising. A paid subscription provides an ad-free experience; non-advertising services such as analytics may remain active. Review the price and billing details shown in Google Play before subscribing.'),
      ('What if a document will not open?', f'Check that the file uses a supported format, has downloaded completely and is accessible to the app. If the issue continues, <a href="{CONTACT}">contact support</a> with the file extension, app version and Android version. Do not send confidential documents.')
    ]
    return '<div class="faq">' + ''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items) + '</div>'

pages = {}
def add(route, title, desc, body, active='', noindex=False):
    pages[route] = (title,desc,body,active,noindex)

