add('/404.html','Page not found | FT PVT. LIMITED','This page could not be found. Return to FT PVT. LIMITED or explore All Document Reader.',f'<div class="wrap"><section class="not-found"><span class="eyebrow">404 · Page not found</span><h1>Let’s get you<br>back on track.</h1><p>The page may have moved, or the address may be incorrect. Find All Document Reader or return to the homepage.</p><div class="actions">{button("Back to home","/")}{button("Explore the app",APP,True)}</div></section></div>',noindex=True)

def render(route,title,desc,body,active,noindex):
    nav = ''.join(f'<a href="{url}"{(" aria-current=\"page\"" if active == key else "")}{(" class=\"nav-contact\"" if key == "contact" else "")}>{label}</a>' for key,label,url in [('home','Home','/'),('apps','Our app','/apps/'),('about','About','/about/'),('contact','Contact us','/contact/')])
    canonical = f'<link rel="canonical" href="{esc(origin+route)}"><meta property="og:url" content="{esc(origin+route)}">' if origin and not noindex else ''
    robots = '<meta name="robots" content="noindex,follow">' if noindex or not origin else '<meta name="robots" content="index,follow">'
    schema = {'@context':'https://schema.org','@type':'Organization','name':COMPANY,'email':EMAIL}
    if origin: schema['url']=origin+'/'
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc)}">{robots}{canonical}<meta name="theme-color" content="#100e1c"><meta property="og:type" content="website"><meta property="og:locale" content="en_US"><meta property="og:site_name" content="{COMPANY}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="{esc(title)}"><meta name="twitter:description" content="{esc(desc)}"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body><a class="skip" href="#main" tabindex="0">Skip to content</a><header class="header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="FT PVT. LIMITED home"><span class="brand-mark" aria-hidden="true">FT</span>{COMPANY}</a><button class="menu" type="button" aria-controls="primary-nav" aria-expanded="false">Menu</button><nav class="nav" id="primary-nav" aria-label="Primary navigation">{nav}</nav></div></header><main id="main" tabindex="-1">{body}</main><footer class="footer"><div class="wrap"><div class="footer-grid"><div class="footer-intro"><a class="brand" href="/"><span class="brand-mark" aria-hidden="true">FT</span>{COMPANY}</a><p>Practical software for everyday documents.<br>The company behind All Document Reader.</p><a class="email" href="mailto:{EMAIL}">{EMAIL}</a></div><nav class="footer-nav" aria-label="Company links"><strong>Explore</strong><a href="/apps/">Our app</a><a href="{APP}">All Document Reader</a><a href="/about/">About us</a><a href="/contact/">Contact</a><a href="/support/">Support</a></nav><nav class="footer-nav" aria-label="Legal links"><strong>The details</strong><a href="/privacy-policy/">Website privacy</a><a href="{POLICY}">App privacy</a><a href="/terms-and-conditions/">Terms &amp; Conditions</a></nav></div><div class="footer-bottom"><span>© 2026 {COMPANY}. All rights reserved.</span><span>Thoughtfully simple. Purposefully useful.</span></div></div></footer></body></html>'''

for route,data in pages.items():
    dest = OUT / (route.lstrip('/') if route.endswith('.html') else route.lstrip('/')+'index.html')
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(render(route,*data),encoding='utf-8')

for old,new in [('/privacy/','/privacy-policy/'),('/terms/','/terms-and-conditions/')]:
    dest=OUT/old.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><meta http-equiv="refresh" content="0;url={new}"><title>Page moved | FT PVT. LIMITED</title><link rel="stylesheet" href="/assets/site.css"></head><body><main class="wrap not-found"><h1>This page has moved.</h1><p><a href="{new}">Continue to {"Privacy Policy" if old == "/privacy/" else "Terms &amp; Conditions"}</a></p></main></body></html>',encoding='utf-8')

# A valid development sitemap is included; production build replaces its origin.
sitemap_origin = origin or 'http://localhost:4173'
routes = [r for r,data in pages.items() if not data[-1]]
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{esc(sitemap_origin+r)}</loc></url>\n' for r in routes)+'</urlset>\n',encoding='utf-8')
(OUT/'robots.txt').write_text('User-agent: *\n'+('Allow: /\nSitemap: '+origin+'/sitemap.xml\n' if origin else 'Disallow: /\n# Preview build: configure your verified domain and rebuild for production.\n'),encoding='utf-8')
(OUT/'_redirects').write_text('/privacy/ /privacy-policy/ 301\n/terms/ /terms-and-conditions/ 301\n',encoding='utf-8')
(OUT/'_headers').write_text('/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: DENY\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n  Content-Security-Policy: default-src \'self\'; script-src \'self\'; style-src \'self\'; img-src \'self\' data:; font-src \'self\'; connect-src \'self\'; object-src \'none\'; base-uri \'self\'; frame-ancestors \'none\'; form-action \'none\'\n',encoding='utf-8')
